-- Nova Iguaçu e arredores: recorte do conjunto places-rio.sql.
-- Fonte: OpenStreetMap/Overture; dados Overture 2026-09-23.1.
-- Créditos e licenças: docs/dados-abertos.md.
-- Recorte lat [-22.88,-22.45], lng [-43.72,-43.34]; 694 lugares.
-- Aplicar depois de 20261201000000_reparar_cadastro_e_mapa.sql.
on conflict (fonte, fonte_id) do update set
  osm_type = excluded.osm_type,
  osm_id = excluded.osm_id,
  nome = excluded.nome,
  categoria = excluded.categoria,
  endereco = excluded.endereco,
  telefone = excluded.telefone,
  horario = excluded.horario,
  website = excluded.website,
  lat = excluded.lat,
  lng = excluded.lng,
  aberto_24h = excluded.aberto_24h,
  aceita_caes = excluded.aceita_caes,
  area_caes = excluded.area_caes;
